<script setup>
import {ref,onMounted,onBeforeUnmount} from 'vue'
import {archive} from '../composables/useArchive'
const emit=defineEmits(['close']);const panel=ref(null);const previous=document.activeElement
function key(e){if(e.key==='Escape')emit('close');if(e.key==='Tab'){const ns=[...panel.value.querySelectorAll('button,a[href]')];if(e.shiftKey&&document.activeElement===ns[0]){e.preventDefault();ns.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===ns.at(-1)){e.preventDefault();ns[0].focus()}}}
onMounted(()=>{document.body.style.overflow='hidden';document.addEventListener('keydown',key);panel.value.querySelector('button').focus()});onBeforeUnmount(()=>{document.body.style.overflow='';document.removeEventListener('keydown',key);previous?.focus()})
</script>
<template><div class="detail-backdrop" @click.self="$emit('close')"><section class="about-panel" ref="panel" role="dialog" aria-modal="true" aria-labelledby="about-title"><header class="detail-header mono"><span>ABOUT / R-ABOUT-01</span><button @click="$emit('close')">× / RECYCLE 回流</button></header><p class="mono">SYSTEM MANUAL / 系统手册 — 02</p><h2 id="about-title">A DATABASE.<br>A RESERVOIR.<br><small>一份档案，一座蓄水池。</small></h2><div class="manual-grid"><section><h3>01 / PROJECT INTRODUCTION / 项目介绍</h3><p>RESERVOIR OPERATING SYSTEM 是一份关于蓄积、停留、承压、达阈、溢出与释放的策展研究档案。</p></section><section><h3>02 / CURATORIAL CONCEPT / 策展观念</h3><p>我们寻找的不是与蓄水池形态相似的事物，而是共享同一种运行机制的事物。水池既是容器，也是理解记忆、身体与社会的研究方法。</p></section><section><h3>03 / RESEARCH METHOD / 研究方法</h3><p>由真实研究表格出发，以分类分区和序号建立唯一档案编号，再与图片文件名对应。保留每一条原始记录，缺失与冲突不以推测补足。</p></section><section><h3>04 / DATABASE LOGIC / 数据逻辑</h3><p>分类与 DREDGE 关键词决定看什么；五种横向视图决定如何看。LEVEL 控制二维列数与图片尺寸；动作只作用于三维中的功能原型和空间原型。</p></section><section><h3>05 / HOW TO USE / 使用方法</h3><p>左右侧栏始终保留，中间区域独立滚动。点击 RELEASE 展开原图，RECYCLE 返回原位。向下进入双关键词关系区。三维中拖动旋转，打开 WHEEL 后滚轮缩放。</p></section><section><h3>06 / AUTHOR / TEAM / 作者与团队</h3><p>研究素材来自本项目提供的 Excel 与图片档案。原始材料未提供项目作者、团队和联系方式。</p></section></div><footer class="mono">{{archive.length}} IMAGES / 张图像 — 6 POSITIONS / 类位置 — 1 SYSTEM / 个系统</footer></section></div></template>
